window.sceneData={"1":[{"context":"Ngày đầu tiên của năm học, ở văn phòng, Vương Nhất Phi chào hỏi trợ giảng AI Tiểu Ngữ.","contextZh":"开学第一天，在办公室里，王一飞和AI助教小语打招呼。","label":"1-1 · Chào hỏi ở văn phòng","lines":[["王一飞","AI小语，你好！","AI Xiǎoyǔ, nǐ hǎo!","Chào AI Tiểu Ngữ!"],["小语","王老师，你好！","Wáng lǎoshī, nǐ hǎo!","Chào cô Vương!"]],"sides":{"小语":"R","王一飞":"L"}},{"context":"Ngày đầu tiên của năm học, trên lớp, các học sinh học cách chào hỏi.","contextZh":"开学第一天，课堂上，学生们学习打招呼用语。","label":"1-2 · Chào hỏi trên lớp","lines":[["王一飞","大家好！","Dàjiā hǎo!","Chào mọi người!"],["学生们","老师，您好！","Lǎoshī, nín hǎo!","Chào cô ạ!"],["小语","你们好！","Nǐmen hǎo!","Chào các bạn!"],["学生们","你好，小语！","Nǐ hǎo, Xiǎoyǔ!","Chào Tiểu Ngữ!"]],"sides":{"学生们":"R","小语":"C","王一飞":"L"}},{"context":"Ngày đầu tiên của năm học, trên lớp, các học sinh học lời cảm ơn và lời tạm biệt.","contextZh":"开学第一天，课堂上，学生们学习致谢语、告别语。","label":"1-3 · Cảm ơn và tạm biệt","lines":[["学生们","谢谢！","Xièxie!","Cảm ơn!"],["小语","不客气！","Bú kèqi!","Không có gì!"],["王一飞","同学们，再见！","Tóngxuémen, zàijiàn!","Tạm biệt các bạn học!"],["学生们","老师，再见！","Lǎoshī, zàijiàn!","Tạm biệt cô ạ!"]],"sides":{"学生们":"L","小语":"R","王一飞":"C"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"1-4 · Bài vè (绕口令)","lines":[["小语","妈种麻，我放马。","Mā zhòng má, wǒ fàng mǎ.","Mẹ trồng gai dầu, tôi thả ngựa."],["小语","马吃麻，妈骂马。","Mǎ chī má, mā mà mǎ.","Ngựa ăn gai dầu, mẹ mắng ngựa."]],"sides":{"小语":"C"}}],"2":[{"context":"Trong lớp học, Vương Nhất Phi đang làm quen với các học sinh.","contextZh":"在教室里，王一飞在认识学生。","label":"2-1 · Hỏi tên trong lớp","lines":[["王一飞","请问，你叫什么名字？","Qǐngwèn, nǐ jiào shénme míngzi?","Xin hỏi, bạn tên là gì?"],["陈天中","我叫陈天中。","Wǒ jiào Chén Tiānzhōng.","Tôi tên là Trần Thiên Trung."]],"sides":{"王一飞":"L","陈天中":"R"}},{"context":"Trong khuôn viên trường, Trần Thiên Trung chào Bạch Gia Nguyệt nhưng nhận nhầm người.","contextZh":"在校园里，陈天中和白家月打招呼时认错了人。","label":"2-2 · Nhận nhầm người","lines":[["陈天中","你好，安妮！","Nǐ hǎo, Ānnī!","Chào An Ni!"],["白家月","你好，陈天中！我不是安妮，我是白家月。","Nǐ hǎo, Chén Tiānzhōng! Wǒ bú shì Ānnī, wǒ shì Bái Jiāyuè.","Chào Trần Thiên Trung! Tôi không phải An Ni, tôi là Bạch Gia Nguyệt."],["陈天中","对不起！","Duìbuqǐ!","Xin lỗi!"],["白家月","没关系！","Méi guānxi!","Không sao đâu!"]],"sides":{"白家月":"R","陈天中":"L"}},{"context":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu.","contextZh":"在校园里，李文和白家月第一次相遇。","label":"2-3 · Gặp nhau lần đầu","lines":[["李文","你好！我叫李文。","Nǐ hǎo! Wǒ jiào Lǐ Wén.","Chào bạn! Tôi tên là Lý Văn."],["白家月","你好！我叫白家月。","Nǐ hǎo! Wǒ jiào Bái Jiāyuè.","Chào bạn! Tôi tên là Bạch Gia Nguyệt."],["李文","很高兴认识你。","Hěn gāoxìng rènshi nǐ.","Rất vui được gặp bạn."],["白家月","认识你我也很高兴。","Rènshi nǐ wǒ yě hěn gāoxìng.","Được gặp bạn tôi cũng rất vui."]],"sides":{"李文":"L","白家月":"R"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"2-4 · Bài vè (绕口令)","lines":[["小语","七加一，再减一，加完减完等于几？","Qī jiā yī, zài jiǎn yī, jiāwán jiǎnwán děngyú jǐ?","Bảy cộng một, rồi trừ một, cộng xong trừ xong bằng mấy?"],["小语","加完减完还是七。","Jiāwán jiǎnwán hái shì qī.","Cộng xong trừ xong vẫn là bảy."]],"sides":{"小语":"C"}}],"3":[{"context":"Trong khuôn viên trường, Lý Văn và Bạch Gia Nguyệt gặp nhau lần đầu và tiếp tục trò chuyện.","contextZh":"在校园里，李文和白家月第一次相遇，两人继续聊天儿。","label":"3-1 · Tôi là người Trung Quốc","lines":[["李文","我是中国人。","Wǒ shì Zhōngguó rén.","Tôi là người Trung Quốc."],["白家月","我是法国人。我的中文老师也是中国人。","Wǒ shì Fǎguó rén. Wǒ de Zhōngwén lǎoshī yě shì Zhōngguó rén.","Tôi là người Pháp. Giáo viên tiếng Trung của tôi cũng là người Trung Quốc."]],"sides":{"李文":"L","白家月":"R"}},{"context":"Trong lớp học, sau giờ học, An Ni đang xem ảnh trong điện thoại của Trần Thiên Trung.","contextZh":"在教室里，下课后，安妮在看陈天中手机里的照片。","label":"3-2 · Đây là ai?","lines":[["安妮","这是谁？","Zhè shì shéi?","Đây là ai?"],["陈天中","这是我女朋友。","Zhè shì wǒ nǚpéngyou.","Đây là bạn gái của tôi."],["安妮","你女朋友是哪国人？","Nǐ nǚpéngyou shì nǎ guó rén?","Bạn gái của bạn là người nước nào?"],["陈天中","她也是泰国人。","Tā yě shì Tàiguó rén.","Cô ấy cũng là người Thái Lan."]],"sides":{"安妮":"L","陈天中":"R"}},{"context":"Ở nhà, Vương Nhất Tuyết gọi video cho Vương Nhất Phi.","contextZh":"在家里，王一雪给王一飞打视频电话。","label":"3-3 · Gọi video cho chị","lines":[["王一雪","喂，一飞！","Wéi, Yīfēi!","A lô, Nhất Phi!"],["王一飞","姐姐！","Jiějie!","Chị ơi!"],["王一雪","你工作还忙吗？","Nǐ gōngzuò hái máng ma?","Công việc của bạn còn bận không?"],["王一飞","对，还很忙。你也很忙吗？","Duì, hái hěn máng. Nǐ yě hěn máng ma?","Đúng, còn rất bận. Bạn cũng rất bận à?"],["王一雪","我不太忙。我们很想你。","Wǒ bú tài máng. Wǒmen hěn xiǎng nǐ.","Tôi không bận lắm. Chúng tôi rất nhớ bạn."],["王一飞","我也想你们。","Wǒ yě xiǎng nǐmen.","Tôi cũng nhớ các bạn."]],"sides":{"王一雪":"L","王一飞":"R"}},{"context":"Bài vè luyện phát âm, đọc theo băng ở cuối bài.","contextZh":"跟读绕口令，练习发音。","label":"3-4 · Bài vè (绕口令)","lines":[["小语","四是四，十是十。","Sì shì sì, shí shì shí.","Bốn là bốn, mười là mười."],["小语","十四是十四，四十是四十。","Shísì shì shísì, sìshí shì sìshí.","Mười bốn là mười bốn, bốn mươi là bốn mươi."]],"sides":{"小语":"C"}}],"4":[{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在家里，刘明和王一雪在聊天儿。","label":"4-1 · Cô ấy có bao nhiêu học sinh?","lines":[["刘明","一飞忙吗？","Yīfēi máng ma?","Nhất Phi có bận không?"],["王一雪","她很忙。","Tā hěn máng.","Cô ấy rất bận."],["刘明","她有多少个学生？","Tā yǒu duōshao gè xuéshēng?","Cô ấy có bao nhiêu học sinh?"],["王一雪","她有二十个学生。","Tā yǒu èrshí gè xuéshēng.","Cô ấy có hai mươi học sinh."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc nghỉ giải lao.","contextZh":"在公司里，王一雪和杨同乐休息时聊天儿。","label":"4-2 · Nhà bạn có mấy người?","lines":[["王一雪","我有两个哥哥，你呢？","Wǒ yǒu liǎng gè gēge, nǐ ne?","Tôi có hai anh trai, còn bạn?"],["杨同乐","我没有哥哥。","Wǒ méiyǒu gēge.","Tôi không có anh trai."],["王一雪","你家有几口人？","Nǐ jiā yǒu jǐ kǒu rén?","Nhà bạn có mấy người?"],["杨同乐","我家有四口人，爸爸、妈妈、妹妹和我。","Wǒ jiā yǒu sì kǒu rén, bàba, māma, mèimei hé wǒ.","Nhà tôi có bốn người: bố, mẹ, em gái và tôi."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Trên phố, Vương Nhất Tuyết dẫn con trai đi chơi thì tình cờ gặp Dương Đồng Lạc.","contextZh":"在街上，王一雪带着儿子偶遇杨同乐。","label":"4-3 · Tôi có hai con","lines":[["杨同乐","这是您儿子吗？","Zhè shì nín érzi ma?","Đây là con trai của cô phải không?"],["王一雪","是的。我有两个孩子，一个儿子，一个女儿。","Shì de. Wǒ yǒu liǎng gè háizi, yí gè érzi, yí gè nǚ'ér.","Vâng. Tôi có hai con, một con trai, một con gái."],["杨同乐","您儿子几岁？","Nín érzi jǐ suì?","Con trai của cô mấy tuổi?"],["王一雪","他今年五岁。","Tā jīnnián wǔ suì.","Cháu năm nay năm tuổi."],["杨同乐","您女儿多大？","Nín nǚ'ér duō dà?","Con gái của cô bao nhiêu tuổi?"],["王一雪","她今年十二。","Tā jīnnián shí'èr.","Cháu năm nay mười hai tuổi."]],"sides":{"杨同乐":"L","王一雪":"R"}}],"5":[{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在家里，刘明和王一雪在聊天儿。","label":"5-1 · Hôm nay là ngày mấy?","lines":[["王一雪","今天几号？","Jīntiān jǐ hào?","Hôm nay là ngày mấy?"],["刘明","今天9月8号。","Jīntiān jiǔ yuè bā hào.","Hôm nay là ngày 8 tháng 9."],["王一雪","星期几？","Xīngqī jǐ?","Hôm nay là thứ mấy?"],["刘明","星期日。今天我休息。","Xīngqīrì. Jīntiān wǒ xiūxi.","Chủ nhật. Hôm nay tôi nghỉ."]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc nghỉ giải lao.","contextZh":"在公司里，王一雪和杨同乐休息时聊天儿。","label":"5-2 · Bạn có biết nấu cơm không?","lines":[["王一雪","你会做饭吗？","Nǐ huì zuò fàn ma?","Bạn có biết nấu cơm không?"],["杨同乐","我会做。","Wǒ huì zuò.","Tôi biết làm."],["王一雪","你会做什么？","Nǐ huì zuò shénme?","Bạn biết làm món gì?"],["杨同乐","我会做面条儿、饺子，也会做一些菜。星期天我也做饭。","Wǒ huì zuò miàntiáor, jiǎozi, yě huì zuò yìxiē cài. Xīngqītiān wǒ yě zuò fàn.","Tôi biết làm mì, sủi cảo, cũng biết làm một số món. Chủ nhật tôi cũng nấu cơm."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Ở công ty, Vương Nhất Tuyết và Dương Đồng Lạc trò chuyện lúc tan làm.","contextZh":"在公司里，王一雪和杨同乐下班时聊天儿。","label":"5-3 · Máy tính mới đẹp thật!","lines":[["王一雪","同乐，下班吗？","Tónglè, xiàbān ma?","Đồng Lạc, tan làm chưa?"],["杨同乐","下班。","Xiàbān.","Tan làm rồi."],["王一雪","这是你的新电脑吗？","Zhè shì nǐ de xīn diànnǎo ma?","Đây là máy tính mới của bạn phải không?"],["杨同乐","是的，是我的新电脑。","Shì de, shì wǒ de xīn diànnǎo.","Vâng, là máy tính mới của tôi."],["王一雪","真好看！","Zhēn hǎokàn!","Đẹp thật đấy!"],["杨同乐","我也很喜欢它。","Wǒ yě hěn xǐhuan tā.","Tôi cũng rất thích nó."]],"sides":{"杨同乐":"R","王一雪":"L"}}],"6":[{"label":"6-1 · Hỏi số điện thoại","context":"Ở trường, Lý Văn hỏi Bạch Gia Nguyệt số điện thoại di động.","contextZh":"在校园里，李文向白家月要手机号。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","家月，你的手机号是多少？","Jiāyuè, nǐ de shǒujīhào shì duōshao?","Gia Nguyệt, số điện thoại di động của bạn là bao nhiêu?"],["白家月","我的手机号是+33 601493190。","Wǒ de shǒujīhào shì sān sān liù líng yāo sì jiǔ sān yāo jiǔ líng.","Số điện thoại di động của tôi là +33 601493190."],["李文","我的手机号是+86 13552721160。","Wǒ de shǒujīhào shì bā liù yāo sān wǔ wǔ èr qī èr yāo yāo liù líng.","Số điện thoại di động của tôi là +86 13552721160."],["白家月","好的。","Hǎo de.","Được rồi."]]},{"label":"6-2 · Đi siêu thị mua đồ","context":"Sau giờ học, ở lớp học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室里，下课后，白家月和陈天中在聊天儿。","sides":{"陈天中":"L","白家月":"R"},"lines":[["陈天中","家月，明天你去哪儿？","Jiāyuè, míngtiān nǐ qù nǎr?","Gia Nguyệt, ngày mai bạn đi đâu?"],["白家月","我想去超市买东西。","Wǒ xiǎng qù chāoshì mǎi dōngxi.","Tôi muốn đi siêu thị mua đồ."],["陈天中","你去超市买什么？","Nǐ qù chāoshì mǎi shénme?","Bạn đi siêu thị mua gì?"],["白家月","我想买些牛奶。","Wǒ xiǎng mǎi xiē niúnǎi.","Tôi muốn mua một ít sữa bò."]]},{"label":"6-3 · Ăn tối ở nhà hàng Tây An","context":"Ở nhà, cả nhà Vương Nhất Tuyết đang bàn kế hoạch ăn tối cuối tuần.","contextZh":"在家里，王一雪全家在讨论周末晚餐安排。","sides":{"王一雪":"L","刘明":"R","刘小雪":"L","刘小明":"R"},"lines":[["王一雪","星期天我们去哪儿吃晚饭？","Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","Chủ nhật chúng ta đi đâu ăn tối?"],["刘明","我还想去西安饭店。","Wǒ hái xiǎng qù Xī'ān Fàndiàn.","Tôi vẫn muốn đến nhà hàng Tây An."],["刘小雪","那边的包子非常好吃，我想吃包子。","Nàbiān de bāozi fēicháng hǎochī, wǒ xiǎng chī bāozi.","Bánh bao bên đó rất ngon, con muốn ăn bánh bao."],["刘小明","妈妈，我想吃米饭，不想吃包子。","Māma, wǒ xiǎng chī mǐfàn, bù xiǎng chī bāozi.","Mẹ ơi, con muốn ăn cơm, không muốn ăn bánh bao."],["王一雪","好的。我们怎么去？","Hǎo de. Wǒmen zěnme qù?","Được rồi. Chúng ta đi bằng cách nào?"],["刘明","坐出租车去。","Zuò chūzūchē qù.","Đi taxi đến đó."]]}],"7":[{"label":"7-1 · Gọi điện hẹn gặp","context":"Bạch Gia Nguyệt và An Ni đang gọi điện cho nhau.","contextZh":"白家月和安妮在打电话。","sides":{"白家月":"L","安妮":"R"},"lines":[["白家月","现在几点？","Xiànzài jǐ diǎn?","Bây giờ là mấy giờ?"],["安妮","早上八点四十。","Zǎoshang bā diǎn sìshí.","Tám giờ bốn mươi buổi sáng."],["白家月","我上午十点十分有课。","Wǒ shàngwǔ shí diǎn shí fēn yǒu kè.","Sáng nay mười giờ mười phút tôi có tiết học."],["安妮","好的，我们下午两点见吧。","Hǎo de, wǒmen xiàwǔ liǎng diǎn jiàn ba.","Được rồi, chiều nay hai giờ chúng ta gặp nhau nhé."]]},{"label":"7-2 · Rủ đi xem phim","context":"Ở trường, Lý Văn gặp Bạch Gia Nguyệt.","contextZh":"在校园里，李文遇到白家月。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","下午我想去电影院看电影，你去吗？","Xiàwǔ wǒ xiǎng qù diànyǐngyuàn kàn diànyǐng, nǐ qù ma?","Chiều nay tôi muốn đi rạp chiếu phim xem phim, bạn đi không?"],["白家月","我不想去，下午还有事。","Wǒ bù xiǎng qù, xiàwǔ hái yǒu shì.","Tôi không muốn đi, chiều nay còn có việc."],["李文","好的。明天呢？","Hǎo de. Míngtiān ne?","Được rồi. Ngày mai thì sao?"],["白家月","我明天下午两点还上课呢，四点半下课。","Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne, sì diǎn bàn xiàkè.","Chiều mai hai giờ tôi vẫn còn học, bốn giờ rưỡi mới tan học."]]},{"label":"7-3 · Gọi điện cho Lưu Minh","context":"Vương Nhất Tuyết ở văn phòng gọi điện cho Lưu Minh.","contextZh":"王一雪在办公室给刘明打电话。","sides":{"王一雪":"L","刘明":"R"},"lines":[["王一雪","喂，你在哪儿呢？","Wèi, nǐ zài nǎr ne?","Alo, bạn đang ở đâu đấy?"],["刘明","我在家里呢。","Wǒ zài jiā li ne.","Tôi đang ở nhà đây."],["王一雪","我晚上六点半下班。","Wǒ wǎnshang liù diǎn bàn xiàbān.","Tôi tan làm lúc sáu giờ rưỡi tối."],["刘明","我八点去医院上班。","Wǒ bā diǎn qù yīyuàn shàngbān.","Tôi tám giờ đi bệnh viện làm việc."],["王一雪","好的，你去店里买些菜吧。","Hǎo de, nǐ qù diàn li mǎi xiē cài ba.","Được rồi, bạn đi cửa hàng mua ít rau nhé."],["刘明","好，我十分钟后去。","Hǎo, wǒ shí fēnzhōng hòu qù.","Được, mười phút nữa tôi đi."]]}],"8":[{"label":"8-1 · Con mèo nhỏ ngoài phòng","context":"Ở nhà Vương Nhất Phi, Bạch Gia Nguyệt và Trần Thiên Trung đến chơi.","contextZh":"在王一飞家，白家月和陈天中来做客。","sides":{"白家月":"L","陈天中":"R"},"lines":[["白家月","房间外有一只小猫。","Fángjiān wài yǒu yì zhī xiǎo māo.","Ngoài phòng có một con mèo nhỏ."],["陈天中","我没看见，它在哪儿呢？","Wǒ méi kànjiàn, tā zài nǎr ne?","Tôi không nhìn thấy nó, nó ở đâu nhỉ?"],["白家月","它在桌子下呢。","Tā zài zhuōzi xià ne.","Nó đang ở dưới gầm bàn đấy."],["陈天中","这只小猫真漂亮！","Zhè zhī xiǎo māo zhēn piàoliang!","Con mèo nhỏ này xinh thật!"]]},{"label":"8-2 · Hẹn gặp trước hiệu sách","context":"Ở lớp học, sau giờ học, Bạch Gia Nguyệt gọi điện cho Lý Văn.","contextZh":"在教室里，下课后，白家月给李文打电话。","sides":{"白家月":"L","李文":"R"},"lines":[["白家月","我们在哪儿见呢？","Wǒmen zài nǎr jiàn ne?","Chúng ta gặp nhau ở đâu nhỉ?"],["李文","在学校书店前见吧。","Zài xuéxiào shūdiàn qián jiàn ba.","Gặp nhau trước hiệu sách của trường nhé."],["白家月","好的。下午两点你能到吗？","Hǎo de. Xiàwǔ liǎng diǎn nǐ néng dào ma?","Được rồi. Chiều nay hai giờ bạn đến được không?"],["李文","我能到。我在学校吃午饭。","Wǒ néng dào. Wǒ zài xuéxiào chī wǔfàn.","Tôi đến được. Tôi ăn trưa ở trường."]]},{"label":"8-3 · Chuyện trò ở bệnh viện","context":"Ở bệnh viện, Lưu Minh và đồng nghiệp là bác sĩ Hồ đang trò chuyện.","contextZh":"在医院里，刘明和同事胡医生在聊天儿。","sides":{"刘明":"L","胡医生":"R"},"lines":[["刘明","小胡，还没吃饭呢？","Xiǎo Hú, hái méi chī fàn ne?","Tiểu Hồ, vẫn chưa ăn cơm à?"],["胡医生","没吃呢。","Méi chī ne.","Chưa ăn."],["刘明","大医院病人多，医生非常忙。","Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","Bệnh viện lớn đông bệnh nhân, bác sĩ rất bận."],["胡医生","是的。我爸爸也在医院工作，他也非常忙。","Shì de. Wǒ bàba yě zài yīyuàn gōngzuò, tā yě fēicháng máng.","Đúng vậy. Bố tôi cũng làm việc ở bệnh viện, ông ấy cũng rất bận."],["刘明","你家有两个医生？","Nǐ jiā yǒu liǎng ge yīshēng?","Nhà bạn có hai bác sĩ à?"],["胡医生","对。","Duì.","Đúng vậy."]]}],"9":[{"label":"9-1 · Hẹn xem phim tối nay","context":"Ở trường, Lý Văn và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在校园里，李文和白家月在聊天儿。","sides":{"李文":"L","白家月":"R"},"lines":[["李文","学校前边有一家电影院。","Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","Trước trường có một rạp chiếu phim."],["白家月","对。我们晚上去那个电影院看电影吧。","Duì. Wǒmen wǎnshang qù nàge diànyǐngyuàn kàn diànyǐng ba.","Đúng vậy. Tối nay chúng ta đến rạp chiếu phim đó xem phim nhé."],["李文","好！我们七点在电影院外边见，好吗？","Hǎo! Wǒmen qī diǎn zài diànyǐngyuàn wàibian jiàn, hǎo ma?","Hay quá! Bảy giờ chúng ta gặp nhau ngoài rạp chiếu phim, được không?"],["白家月","好的，晚上七点见！","Hǎo de, wǎnshang qī diǎn jiàn!","Được rồi, tối nay bảy giờ gặp nhau!"]]},{"label":"9-2 · Quyển sách trên ghế","context":"Ở lớp học, sau giờ học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室里，下课后，白家月和陈天中在对话。","sides":{"白家月":"L","陈天中":"R"},"lines":[["白家月","椅子上有一本中文书，那是谁的书？","Yǐzi shang yǒu yì běn Zhōngwén shū, nà shì shéi de shū?","Trên ghế có một quyển sách tiếng Trung, đó là sách của ai?"],["陈天中","是我的书，谢谢。这是我的第二本中文书。","Shì wǒ de shū, xièxie. Zhè shì wǒ de dì-èr běn Zhōngwén shū.","Là sách của tôi, cảm ơn. Đây là quyển sách tiếng Trung thứ hai của tôi."],["白家月","不客气。你明天上午在哪儿？","Bú kèqi. Nǐ míngtiān shàngwǔ zài nǎr?","Không có gì. Sáng mai bạn ở đâu?"],["陈天中","我明天上午在学校学习。","Wǒ míngtiān shàngwǔ zài xuéxiào xuéxí.","Sáng mai tôi học ở trường."]]},{"label":"9-3 · Kế hoạch cuối tuần","context":"Trong giờ nghỉ ở văn phòng, Vương Nhất Tuyết và Dương Đồng Lạc bàn về cuộc sống cuối tuần.","contextZh":"在办公室里，休息时，王一雪和杨同乐谈论周末生活。","sides":{"王一雪":"L","杨同乐":"R"},"lines":[["王一雪","明天星期六，你做什么？","Míngtiān Xīngqīliù, nǐ zuò shénme?","Ngày mai là thứ bảy, bạn làm gì?"],["杨同乐","我白天在家里读书，晚上和朋友们去外边唱歌。","Wǒ báitiān zài jiā li dúshū, wǎnshang hé péngyoumen qù wàibian chàng gē.","Ban ngày tôi đọc sách ở nhà, buổi tối cùng các bạn ra ngoài hát."],["王一雪","你唱歌很好听。","Nǐ chàng gē hěn hǎotīng.","Bạn hát rất hay."],["杨同乐","谢谢！您星期六做什么？","Xièxie! Nín Xīngqīliù zuò shénme?","Cảm ơn! Thứ bảy chị làm gì ạ?"],["王一雪","我在家里做饭、看电视，和孩子们、小狗玩。","Wǒ zài jiā li zuò fàn, kàn diànshì, hé háizimen, xiǎo gǒu wán.","Tôi nấu cơm, xem ti vi ở nhà, và chơi với các con cùng chú chó nhỏ."],["杨同乐","我也有一只小狗。","Wǒ yě yǒu yì zhī xiǎo gǒu.","Tôi cũng có một chú chó nhỏ."]]}],"10":[{"label":"10-1 · Mua cốc ở cửa hàng nhỏ","context":"Ở một cửa hàng nhỏ, Vương Nhất Tuyết đang mua cốc.","contextZh":"在一家小店，王一雪在买杯子。","sides":{"王一雪":"L","售货员":"R"},"lines":[["王一雪","请问，有杯子吗？","Qǐngwèn, yǒu bēizi ma?","Xin hỏi, có cốc không ạ?"],["售货员","有，杯子在这边。","Yǒu, bēizi zài zhèbiān.","Có, cốc ở bên này."],["王一雪","多少钱一个？","Duōshao qián yí ge?","Một cái bao nhiêu tiền?"],["售货员","这些五块钱一个，那些十块钱一个。","Zhèxiē wǔ kuài qián yí ge, nàxiē shí kuài qián yí ge.","Những cái này năm đồng một cái, những cái kia mười đồng một cái."],["王一雪","我买这个吧。","Wǒ mǎi zhège ba.","Tôi mua cái này nhé."]]},{"label":"10-2 · Mua táo ở chợ","context":"Ở chợ, Vương Nhất Tuyết đang mua hoa quả.","contextZh":"在菜市场，王一雪在买水果。","sides":{"王一雪":"L","售货员":"R"},"lines":[["王一雪","这儿的水果真不少！","Zhèr de shuǐguǒ zhēn bù shǎo!","Hoa quả ở đây nhiều thật!"],["售货员","您想买什么？","Nín xiǎng mǎi shénme?","Ngài muốn mua gì ạ?"],["王一雪","我想买两斤苹果。","Wǒ xiǎng mǎi liǎng jīn píngguǒ.","Tôi muốn mua hai cân táo."],["售货员","苹果三块五一斤。这些七块二，七块钱吧。","Píngguǒ sān kuài wǔ yì jīn. Zhèxiē qī kuài èr, qī kuài qián ba.","Táo ba đồng rưỡi một cân. Những thứ này bảy đồng hai, tính bảy đồng nhé."],["王一雪","好的，这儿的苹果真便宜！","Hǎo de, zhèr de píngguǒ zhēn piányi!","Được rồi, táo ở đây rẻ thật!"]]},{"label":"10-3 · Mua quần áo cho con","context":"Ở trung tâm thương mại, Lưu Minh và Vương Nhất Tuyết đang mua quần áo cho các con.","contextZh":"在商场里，刘明和王一雪在给孩子买衣服。","sides":{"王一雪":"L","刘明":"R"},"lines":[["王一雪","这家商店衣服真多！这件一百元，怎么样？","Zhè jiā shāngdiàn yīfu zhēn duō! Zhè jiàn yìbǎi yuán, zěnmeyàng?","Cửa hàng này nhiều quần áo thật! Cái này một trăm đồng, thế nào?"],["刘明","好看，也不贵。","Hǎokàn, yě bù guì.","Đẹp, cũng không đắt."],["王一雪","小雪能穿，买一件吧。","Xiǎoxuě néng chuān, mǎi yí jiàn ba.","Tiểu Tuyết mặc được, mua một cái nhé."],["刘明","好的。小明能穿吗？","Hǎo de. Xiǎomíng néng chuān ma?","Được rồi. Tiểu Minh có mặc được không?"],["王一雪","不能。这些是女孩子穿的衣服，男孩子的衣服在那儿。","Bù néng. Zhèxiē shì nǚ háizi chuān de yīfu, nán háizi de yīfu zài nàr.","Không được. Đây là quần áo con gái mặc, quần áo con trai ở đằng kia."],["刘明","好的。","Hǎo de.","Được rồi."]]}],"11":[{"context":"Trên đường, Lý Văn đang tìm nhà hàng thì Vương Nhất Phi gọi điện cho anh.","contextZh":"在路上，李文在找饭店，王一飞给他打电话。","label":"11-1 · Tìm nhà hàng trên đường","lines":[["王一飞","喂，李文，你什么时候能到饭店？","Wèi, Lǐ Wén, nǐ shénme shíhou néng dào fàndiàn?","A lô, Lý Văn, bao giờ anh đến được nhà hàng?"],["李文","还不知道，正在找呢。它是不是在超市后边？","Hái bù zhīdào, zhèngzài zhǎo ne. Tā shì bu shì zài chāoshì hòubian?","Vẫn chưa biết, tôi đang tìm đây. Nó có phải ở phía sau siêu thị không?"],["王一飞","是的。你开车没开车？","Shì de. Nǐ kāichē méi kāichē?","Đúng rồi. Anh có lái xe không?"],["李文","我没开车，坐车呢。","Wǒ méi kāichē, zuò chē ne.","Tôi không lái xe, tôi đang ngồi xe đây."]],"sides":{"李文":"R","王一飞":"L"}},{"context":"Ở nhà hàng, Vương Nhất Phi và Lý Văn gặp nhau rồi trò chuyện.","contextZh":"在饭店里，王一飞和李文见面后聊天儿。","label":"11-2 · Gặp nhau ở nhà hàng","lines":[["王一飞","你还在读大学吗？","Nǐ hái zài dú dàxué ma?","Anh vẫn còn đang học đại học à?"],["李文","对，我读大学呢，还是大学生。","Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","Đúng, tôi đang học đại học đây, vẫn còn là sinh viên."],["王一飞","你们学习忙不忙？","Nǐmen xuéxí máng bu máng?","Các anh học có bận không?"],["李文","非常忙，我学医，我们的课很多。","Fēicháng máng, wǒ xué yī, wǒmen de kè hěn duō.","Rất bận, tôi học y, chúng tôi có rất nhiều tiết học."]],"sides":{"李文":"R","王一飞":"L"}},{"context":"Sáng thứ Bảy, Lưu Minh sắp đi bệnh viện làm thêm, trước khi ra khỏi nhà anh trò chuyện với con gái.","contextZh":"星期六早上，刘明要去医院加班，出门前和女儿对话。","label":"11-3 · Sáng thứ Bảy ở nhà","lines":[["刘明","弟弟起床没起床呢？","Dìdi qǐchuáng méi qǐchuáng ne?","Em trai đã dậy chưa?"],["刘小雪","没起床呢，还在睡觉。","Méi qǐchuáng ne, hái zài shuìjiào.","Chưa dậy đâu, vẫn còn đang ngủ."],["刘明","还睡呢？他今天去不去哪里？","Hái shuì ne? Tā jīntiān qù bu qù nǎlǐ?","Vẫn còn ngủ à? Hôm nay nó có đi đâu không?"],["刘小雪","去哪里？","Qù nǎlǐ?","Đi đâu ạ?"],["刘明","去超市。","Qù chāoshì.","Đi siêu thị."],["刘小雪","我昨天问他，他对我说，他不去，他今天要和小朋友玩。","Wǒ zuótiān wèn tā, tā duì wǒ shuō, tā bú qù, tā jīntiān yào hé xiǎopéngyǒu wán.","Hôm qua con hỏi nó, nó nói với con là nó không đi, hôm nay nó muốn chơi với các bạn nhỏ."]],"sides":{"刘小雪":"R","刘明":"L"}}],"12":[{"context":"Vương Nhất Tuyết gọi điện cho Vương Nhất Phi hỏi tình hình bên chỗ chị.","contextZh":"王一雪给王一飞打电话，问问王一飞那边的情况。","label":"12-1 · Gọi điện hỏi thời tiết","lines":[["王一雪","今天天气怎么样？","Jīntiān tiānqì zěnmeyàng?","Hôm nay thời tiết thế nào?"],["王一飞","这里的天不太好，下雨了。","Zhèlǐ de tiān bú tài hǎo, xià yǔ le.","Thời tiết chỗ chị không tốt lắm, trời đang mưa."],["王一雪","雨大吗？","Yǔ dà ma?","Mưa to không?"],["王一飞","有点儿大，我觉得很冷。","Yǒudiǎnr dà, wǒ juéde hěn lěng.","Hơi to, chị thấy rất lạnh."]],"sides":{"王一雪":"L","王一飞":"R"}},{"context":"Trong thang máy công ty, Vương Nhất Tuyết và Dương Đồng Lạc đang trò chuyện.","contextZh":"在公司电梯里，王一雪和杨同乐在聊天儿。","label":"12-2 · Gặp nhau trong thang máy","lines":[["王一雪","昨天下雪了。","Zuótiān xià xuě le.","Hôm qua trời có tuyết rơi."],["杨同乐","是的，太冷了。","Shì de, tài lěng le.","Đúng thế, lạnh quá."],["王一雪","你昨天没来公司，生病了？","Nǐ zuótiān méi lái gōngsī, shēngbìng le?","Hôm qua anh không đến công ty, bị ốm à?"],["杨同乐","对，我昨天去医院看病了。","Duì, wǒ zuótiān qù yīyuàn kànbìng le.","Đúng, hôm qua tôi đi bệnh viện khám bệnh."]],"sides":{"杨同乐":"R","王一雪":"L"}},{"context":"Hôm qua ở bệnh viện, bác sĩ khám bệnh cho Dương Đồng Lạc.","contextZh":"昨天在医院，医生给杨同乐看病。","label":"12-3 · Khám bệnh ở bệnh viện","lines":[["杨同乐","医生，我病了。","Yīshēng, wǒ bìng le.","Bác sĩ, tôi bị ốm."],["胡医生","我看看。你觉得怎么样？","Wǒ kànkan. Nǐ juéde zěnmeyàng?","Để tôi xem nào. Anh thấy trong người thế nào?"],["杨同乐","我很冷。","Wǒ hěn lěng.","Tôi thấy rất lạnh."],["胡医生","好的，吃一点儿药，今天休息半天吧。","Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","Được, uống một ít thuốc, hôm nay nghỉ nửa ngày nhé."],["杨同乐","好的。","Hǎo de.","Vâng."],["胡医生","回家后再喝些热水。","Huí jiā hòu zài hē xiē rè shuǐ.","Về nhà rồi uống thêm ít nước nóng nhé."]],"sides":{"杨同乐":"L","胡医生":"R"}}],"13":[{"context":"Trong lớp học, sau giờ học, Bạch Gia Nguyệt hỏi cô Vương một câu hỏi.","contextZh":"在教室里，下课后，白家月问王老师问题。","label":"13-1 · Hỏi thêm cô giáo một câu","lines":[["白家月","王老师，我可以再问您一个问题吗？","Wáng lǎoshī, wǒ kěyǐ zài wèn nín yí ge wèntí ma?","Cô Vương, em có thể hỏi thêm cô một câu nữa không ạ?"],["王一飞","可以。你有什么问题？","Kěyǐ. Nǐ yǒu shénme wèntí?","Được. Em có câu hỏi gì?"],["白家月","那个小店卖不卖手机？","Nàge xiǎo diàn mài bu mài shǒujī?","Cửa hàng nhỏ kia có bán điện thoại không ạ?"],["王一飞","我不知道。你可以打电话问一下。","Wǒ bù zhīdào. Nǐ kěyǐ dǎ diànhuà wèn yíxià.","Cô không biết. Em có thể gọi điện hỏi thử xem."]],"sides":{"王一飞":"R","白家月":"L"}},{"context":"Ở quán cà phê, Vương Nhất Tuyết muốn ăn sáng.","contextZh":"在咖啡馆里，王一雪想吃早餐。","label":"13-2 · Gọi món ở quán cà phê","lines":[["服务员","女士，请坐！您喝什么？","Nǚshì, qǐng zuò! Nín hē shénme?","Thưa cô, mời cô ngồi! Cô uống gì ạ?"],["王一雪","我看一下。请给我一杯牛奶。","Wǒ kàn yíxià. Qǐng gěi wǒ yì bēi niúnǎi.","Để tôi xem một chút. Cho tôi một ly sữa."],["服务员","好的。您还要什么？","Hǎo de. Nín hái yào shénme?","Vâng. Cô còn muốn gì nữa ạ?"],["王一雪","我还没吃早饭，再要这个面包和鸡蛋吧。","Wǒ hái méi chī zǎofàn, zài yào zhège miànbāo hé jīdàn ba.","Tôi vẫn chưa ăn sáng, cho thêm bánh mì và trứng này nhé."]],"sides":{"服务员":"L","王一雪":"R"}},{"context":"Ở nhà hàng, Lưu Minh đang gọi món.","contextZh":"在餐馆里，刘明在点餐。","label":"13-3 · Gọi món ở nhà hàng","lines":[["服务员","先生，请坐！您要什么？","Xiānsheng, qǐng zuò! Nín yào shénme?","Thưa ông, mời ông ngồi! Ông muốn gì ạ?"],["刘明","我要一斤饺子。","Wǒ yào yì jīn jiǎozi.","Tôi muốn một cân sủi cảo."],["服务员","好的。一斤饺子40个。","Hǎo de. Yì jīn jiǎozi sìshí gè.","Vâng. Một cân sủi cảo là 40 cái."],["刘明","40个太多了，我要一半吧。","Sìshí gè tài duō le, wǒ yào yíbàn ba.","40 cái nhiều quá, tôi lấy một nửa thôi."],["服务员","半斤20个。您想喝什么？","Bàn jīn èrshí gè. Nín xiǎng hē shénme?","Nửa cân là 20 cái. Ông muốn uống gì ạ?"],["刘明","请给我一杯茶吧。","Qǐng gěi wǒ yì bēi chá ba.","Cho tôi một ly trà nhé."]],"sides":{"刘明":"R","服务员":"L"}}],"14":[{"context":"Trong lớp học, sau giờ học, Bạch Gia Nguyệt và Trần Thiên Trung bàn về chuyến đi ngoại khóa lần trước.","contextZh":"在教室里，下课后，白家月和陈天中在谈论上一次课外旅行。","label":"14-1 · Kể chuyện đi tàu hỏa","lines":[["白家月","你们上火车后看见王老师了吗？","Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","Sau khi lên tàu các cậu có nhìn thấy cô Vương không?"],["陈天中","没看见。中午车开后，有些人在看书，有些人睡觉了。","Méi kànjiàn. Zhōngwǔ chē kāi hòu, yǒuxiē rén zài kàn shū, yǒuxiē rén shuìjiào le.","Không thấy. Sau khi tàu chạy buổi trưa, có người đọc sách, có người đã ngủ."],["白家月","你呢？","Nǐ ne?","Còn cậu thì sao?"],["陈天中","我看了一个电影。","Wǒ kànle yí ge diànyǐng.","Tôi đã xem một bộ phim."]],"sides":{"白家月":"L","陈天中":"R"}},{"context":"Trên lớp, Vương Nhất Phi hỏi học sinh về tình hình học tập.","contextZh":"在课堂上，王一飞询问学生们的学习情况。","label":"14-2 · Cô giáo hỏi tình hình học tập","lines":[["王一飞","你们会说汉语了，也会写汉字了吗？","Nǐmen huì shuō Hànyǔ le, yě huì xiě Hànzì le ma?","Các em đã biết nói tiếng Hán rồi, cũng biết viết chữ Hán chưa?"],["白家月","我们都会写了。","Wǒmen dōu huì xiě le.","Chúng em đều biết viết rồi ạ."],["陈天中","老师，我听不见。","Lǎoshī, wǒ tīng bú jiàn.","Cô ơi, em không nghe thấy."],["王一飞","请大家不要说话！请听老师的问题：你们都会写哪些汉字了？","Qǐng dàjiā búyào shuōhuà! Qǐng tīng lǎoshī de wèntí: Nǐmen dōu huì xiě nǎxiē Hànzì le?","Mọi người đừng nói chuyện nữa! Hãy nghe câu hỏi của cô: các em đều biết viết những chữ Hán nào rồi?"],["陈天中","我会写这些字了，您看！","Wǒ huì xiě zhèxiē zì le, nín kàn!","Em biết viết những chữ này rồi, cô xem này!"]],"sides":{"王一飞":"L","白家月":"R","陈天中":"C"}},{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang bàn về việc học lên của các con.","contextZh":"在家里，刘明和王一雪在谈论孩子的升学情况。","label":"14-3 · Bàn chuyện con đi học","lines":[["刘明","明年女儿上中学。","Míngnián nǚ'ér shàng zhōngxué.","Sang năm con gái sẽ lên trung học."],["王一雪","对。儿子也上小学了。","Duì. Érzi yě shàng xiǎoxué le.","Đúng thế. Con trai cũng sẽ vào tiểu học."],["刘明","我们家有了一个中学生。","Wǒmen jiā yǒule yí ge zhōngxuéshēng.","Nhà mình sẽ có một học sinh trung học."],["王一雪","还有了一个小学生。","Hái yǒule yí ge xiǎoxuéshēng.","Còn có thêm một học sinh tiểu học nữa."],["刘明","上学后，他们都忙了。","Shàngxué hòu, tāmen dōu máng le.","Sau khi đi học, chúng nó đều sẽ bận."],["王一雪","是的。太晚了，睡觉吧。","Shì de. Tài wǎn le, shuìjiào ba.","Đúng thế. Muộn quá rồi, đi ngủ thôi."]],"sides":{"刘明":"L","王一雪":"R"}}],"15":[{"context":"Ở nhà Lý Văn, Lý Văn mời Trần Thiên Trung, Bạch Gia Nguyệt và các bạn nếm thử món ăn Trung Quốc.","contextZh":"在李文家，李文邀请陈天中、白家月等朋友品尝中餐。","label":"15-1 · Mời bạn ăn cơm Tàu","lines":[["李文","你们爱吃哪个菜？","Nǐmen ài chī nǎge cài?","Các bạn thích ăn món nào?"],["白家月","我喜欢这个，也喜欢那个。","Wǒ xǐhuan zhège, yě xǐhuan nàge.","Tôi thích món này, cũng thích món kia."],["陈天中","这些菜都好吃，还很好看。","Zhèxiē cài dōu hǎochī, hái hěn hǎokàn.","Những món này đều ngon, lại còn rất đẹp mắt."],["李文","我爱吃中国菜，也喜欢做。大家多吃点儿。","Wǒ ài chī Zhōngguó cài, yě xǐhuan zuò. Dàjiā duō chī diǎnr.","Tôi thích ăn món Trung Quốc, cũng thích nấu. Mọi người ăn nhiều vào nhé."]],"sides":{"李文":"L","白家月":"R","陈天中":"C"}},{"context":"Ở nhà Lý Văn, mọi người vừa ăn cơm vừa bàn kế hoạch nghỉ lễ.","contextZh":"在李文家，大家边吃饭边谈论假期计划。","label":"15-2 · Bàn kế hoạch nghỉ lễ","lines":[["李文","你们都想去哪儿？","Nǐmen dōu xiǎng qù nǎr?","Các bạn đều muốn đi đâu?"],["安妮","去年我和男朋友去了西安，今年我想去北京。","Qùnián wǒ hé nánpéngyou qùle Xī'ān, jīnnián wǒ xiǎng qù Běijīng.","Năm ngoái tôi và bạn trai đã đi Tây An, năm nay tôi muốn đi Bắc Kinh."],["白家月","前几年我去了西安，非常好玩儿。今年我也想去北京。","Qián jǐ nián wǒ qùle Xī'ān, fēicháng hǎowánr. Jīnnián wǒ yě xiǎng qù Běijīng.","Mấy năm trước tôi đã đi Tây An, rất vui. Năm nay tôi cũng muốn đi Bắc Kinh."],["李文","我和王老师都是北京人，北京非常漂亮。","Wǒ hé Wáng lǎoshī dōu shì Běijīng rén, Běijīng fēicháng piàoliang.","Tôi và cô Vương đều là người Bắc Kinh, Bắc Kinh rất đẹp."]],"sides":{"安妮":"R","李文":"L","白家月":"C"}},{"context":"Ngoài lớp học, Bạch Gia Nguyệt, An Ni và cô Vương đang bàn chuyện đi du lịch Bắc Kinh.","contextZh":"在教室外，白家月、安妮和王老师在谈论去北京旅游的事。","label":"15-3 · Hẹn gặp ở sân bay Đại Hưng","lines":[["王一飞","你们的飞机到北京要几个小时？","Nǐmen de fēijī dào Běijīng yào jǐ ge xiǎoshí?","Máy bay của các em đến Bắc Kinh mất mấy tiếng?"],["白家月","九个小时。","Jiǔ ge xiǎoshí.","Chín tiếng ạ."],["王一飞","我家人都在北京，星期天我姐姐也有时间，她可以去机场接你们，你们也可以住我家。","Wǒ jiārén dōu zài Běijīng, Xīngqītiān wǒ jiějie yě yǒu shíjiān, tā kěyǐ qù jīchǎng jiē nǐmen, nǐmen yě kěyǐ zhù wǒ jiā.","Gia đình cô đều ở Bắc Kinh, chủ nhật chị gái cô cũng rảnh, chị ấy có thể ra sân bay đón các em, các em cũng có thể ở nhà cô."],["安妮","我们星期日早上八点到大兴机场，早不早？","Wǒmen Xīngqīrì zǎoshang bā diǎn dào Dàxīng Jīchǎng, zǎo bu zǎo?","Chúng em sáng chủ nhật 8 giờ đến sân bay Đại Hưng, có sớm quá không ạ?"],["王一飞","不早。","Bù zǎo.","Không sớm đâu."],["白家月","谢谢老师！那我们和您姐姐在大兴机场见！","Xièxie lǎoshī! Nà wǒmen hé nín jiějie zài Dàxīng Jīchǎng jiàn!","Cảm ơn cô ạ! Vậy chúng em hẹn gặp chị gái cô ở sân bay Đại Hưng nhé!"]],"sides":{"安妮":"C","王一飞":"L","白家月":"R"}}]};
